from fractions import Fraction as F


def original(a):
    """Evaluate the original expression exactly; raise ZeroDivisionError outside its domain."""
    a = F(a)
    den1 = a * a + 6 * a + 9      # (a+3)^2 must be nonzero
    num2 = a - 3                  # divisor (a-3)/(a^2+3a) must be nonzero
    den2 = a * a + 3 * a          # divisor's denominator must be nonzero
    den3 = a - 1                  # (a-a^2)/(a-1) needs a != 1
    if den1 == 0 or num2 == 0 or den2 == 0 or den3 == 0:
        raise ZeroDivisionError
    t1 = F(a * a - 9) / den1
    t2 = t1 / (F(num2) / den2)    # division of fractions
    t3 = F(a - a * a) / den3
    return t2 - t3


def simplified(a):
    """Candidate simplified form derived by hand: 2a."""
    return 2 * F(a)


# 1) Exhaustive check over the candidate set {0,1,2,3}
candidates = [0, 1, 2, 3]
valid_values = {}
for a in candidates:
    try:
        val = original(a)
        valid_values[a] = val
        print(f"a={a}: original={val}, simplified={simplified(a)}, "
              f"match={val == simplified(a)}")
    except ZeroDivisionError:
        print(f"a={a}: undefined in the original expression")

# 2) Sampling check that the simplification 2a holds on the general domain
#    (sampling only; supports the identity but does not prove it universally)
samples = [F(p, q) for p in range(-20, 21) for q in range(1, 6)]
bad = []
for s in samples:
    if s in (0, 1, -3, 3):
        continue
    try:
        if original(s) != simplified(s):
            bad.append(s)
    except ZeroDivisionError:
        pass
print(f"sampled rationals checked: {len(samples)}, mismatches: {len(bad)}")

# 3) Compare the submitted answer with the value at the only valid candidate
submitted = F(1)
print(f"valid candidates: {sorted(valid_values.keys())}")
for a, v in valid_values.items():
    print(f"a={a} gives {v}")

if set(valid_values.keys()) == {2} and valid_values[2] == submitted:
    print("CHECK PASS")
elif set(valid_values.keys()) == {2} and valid_values[2] != submitted:
    print(f"submitted answer {submitted} != expected {valid_values[2]} at a=2")
    print("CHECK FAIL")
else:
    print("CHECK UNKNOWN")
