    c = {"FN": 0, "RN": 0, "FP": 0, "RP": 0}
    for _, origin, genre in sel:
        c[origin + genre] += 1
    c["P"] = c["FP"] + c["RP"]
    c["N"] = c["FN"] + c["RN"]
    c["F"] = c["FN"] + c["FP"]
    return c


def valid(sel):
