import re

WORDS = {'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
         'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10}
OP_SYMS = ['][', '<>', '+', '-', '*', ':', '~', '#', '!']
OP_CHARS = set('+-*:~#!<>][')


def is_prime(n):
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True


def bang(a, b):
    return a + b if a - b > 0 else a * b


def colon(a, b):
    return a * b if a - b > 0 else (-a) * (-b)


def tilde(a, b):
    if abs(a - b) < 2:
        return colon(b, a) - b
    return colon(a, b) - a


def hsh(a, b):
    if b < 2:
        return bang(tilde(a, a), b)
    return bang(tilde(b, b), a)


def ltgt(a, b):
    g = math.gcd(a, b)
    return hsh(a, b) if g == 1 else g


def brk(a, b):
    if is_prime(a) or is_prime(b):
        return min(a, b)
    return max(a, b)


F = {
    '+': lambda a, b: a + b,
    '-': lambda a, b: a - b,
    '*': lambda a, b: a * b,
    ':': colon,
    '~': tilde,
    '#': hsh,
    '!': bang,
    '<>': ltgt,
    '][': brk,
}


def split_ops(s):
    out, i = [], 0
    while i < len(s):
        for sym in OP_SYMS:
            if s.startswith(sym, i):
                out.append(sym)
                i += len(sym)
                break
        else:
            raise ValueError("bad operator string: " + s)
    return out


def is_op(tok):
    return len(tok) > 0 and all(c in OP_CHARS for c in tok)


def lex(text):
    return text.replace('(', ' ( ').replace(')', ' ) ').split()


def parse_primary(toks, pos):
    if pos >= len(toks):
        raise ValueError("unexpected end")
    t = toks[pos]
    if t == '(':
        v, pos = parse_expr(toks, pos + 1)
        if pos >= len(toks) or toks[pos] != ')':
            raise ValueError("missing )")
        return v, pos + 1
    if re.fullmatch(r'-?\d+', t):
        return int(t), pos + 1
    if t in WORDS:
        return WORDS[t], pos + 1
    raise ValueError("bad operand: " + t)


def parse_expr(toks, pos):
    # Chain semantics: a op1op2...opk b == (...((a op1 b) op2 b)...) opk b
    val, pos = parse_primary(toks, pos)
    while pos < len(toks) and is_op(toks[pos]):
        syms = split_ops(toks[pos])
        pos += 1
        rhs, pos = parse_primary(toks, pos)
        for s in syms:
            val = F[s](val, rhs)
    return val, pos


def evaluate(text):
    toks = lex(text)
    v, p = parse_expr(toks, 0)
    if p != len(toks):
        raise ValueError("trailing tokens")
    return v


