import math
import re

# Convention: "a X1X2...Xk b" is evaluated left to right as (((a X1 b) X2 b) ... Xk b).
# With two symbols this is exactly the stated rule a <op1><op2> b = (a op1 b) op2 b.
# Symbols are matched greedily against the base operators and +, -, *.

WORDS = {'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
         'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10}


def is_prime(n):
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0:
        return False
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True


def bang(a, b):
    return (a + b) if (a - b > 0) else (a * b)


def colon(a, b):
    return (a * b) if (a - b > 0) else ((-a) * (-b))


def tilde(a, b):
    if abs(a - b) < 2:
        return colon(b, a) - b
    return colon(a, b) - a


def hsh(a, b):
    if b < 2:
        return bang(tilde(a, a), b)
    return bang(tilde(b, b), a)


def ltgt(a, b):
    g = math.gcd(a, b)
    if g == 1:
        return hsh(a, b)
    return g


def brk(a, b):
    if is_prime(a) or is_prime(b):
        return min(a, b)
    return max(a, b)


BASE = {
    '+': lambda a, b: a + b,
    '-': lambda a, b: a - b,
    '*': lambda a, b: a * b,
    '!': bang,
    ':': colon,
    '~': tilde,
    '#': hsh,
    '<>': ltgt,
    '][': brk,
}
SYMS = ['][', '<>', '+', '-', '*', '!', ':', '~', '#']


def split_ops(op):
    out = []
    i = 0
    while i < len(op):
        for s in SYMS:
            if op.startswith(s, i):
                out.append(s)
                i += len(s)
                break
        else:
            raise ValueError('unknown operator symbol at: ' + op[i:])
    return out


def apply_op(op, a, b):
    v = a
    for s in split_ops(op):
        v = BASE[s](v, b)
    return v


def evaluate(src):
    toks = re.findall(r'\(|\)|-?\d+|[A-Za-z]+|[+\-*:~#!<>\[\]]+', src)
    state = {'i': 0}

    def peek():
        return toks[state['i']] if state['i'] < len(toks) else None

    def take():
        t = toks[state['i']]
        state['i'] += 1
        return t

    def atom():
        t = take()
        if t == '(':
            v = expr()
            if take() != ')':
                raise ValueError('expected )')
            return v
        if re.fullmatch(r'-?\d+', t):
            return int(t)
        if t in WORDS:
            return WORDS[t]
        raise ValueError('bad operand: ' + t)

    def expr():
        v = atom()
        while peek() is not None and peek() != ')':
            op = take()
            w = atom()
            v = apply_op(op, v, w)
        return v

    result = expr()
    if state['i'] != len(toks):
        raise ValueError('unparsed tokens remain')
    return result


