import json
import math
import re

# Word-to-number map for the operands written as words.
WORDS = {'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
         'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10}


def isprime(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True


def amp(a, b):      # a & b
    return (a - b) if a * b > 0 else (a + b)


def at(a, b):       # a @ b
    return (amp(a, b)) if a * b > 0 else (a + b)


def bang(a, b):     # a ! b
    if isprime(a) or isprime(b):
        return min(a, b)
    return max(a, b)


def hsh(a, b):      # a # b
    g = math.gcd(a, b)
    return at(a, b) if g == 1 else g


OPS = {
    '&': amp,
    '!': bang,
    '@': at,
    '#': hsh,
    '*': lambda a, b: a * b,
    '+': lambda a, b: a + b,
    '-': lambda a, b: a - b,
}


def apply_op(a, sym_seq, b):
    # "a op1op2...opk b" means (((a op1 b) op2 b) ... opk b)
    r = a
    for s in sym_seq:
        r = OPS[s](r, b)
    return r


TOKEN_RE = re.compile(r'\(|\)|-?\d+|[A-Za-z]+|[&!@#*+\-]+')


def tokenize(s):
    s = s.strip().rstrip('.')
    return TOKEN_RE.findall(s)


def to_num(t):
    if re.fullmatch(r'-?\d+', t):
        return int(t)
    if t in WORDS:
        return WORDS[t]
    raise ValueError("bad operand: " + t)


def parse(toks, i):
    t = toks[i]
    if t == '(':
        left, i = parse(toks, i + 1)
        op = toks[i]
        if not op or any(c not in OPS for c in op):
            raise ValueError("bad operator: " + op)
        i += 1
        right, i = parse(toks, i)
        if toks[i] != ')':
            raise ValueError("expected ')'")
        return apply_op(left, op, right), i + 1
    return to_num(t), i + 1


def evaluate(s):
    toks = tokenize(s)
    val, idx = parse(toks, 0)
    if idx != len(toks):
        raise ValueError("trailing tokens")
    return val


A_STR = "((((((((((((-6 @ six) -& 4) --& -6) @## one) *!# one) #& -3) -! -10) & -2) * 3) *@ four) & -3) *# 10)"
B_STR = "((((((((((((((((((((-5 - 9) * three) -+ -9) #* -2) &!# one) # -7) -# -4) + two) +- -3) #*# -7) #& five) # -6) -&+ 4) @ -7) +!- -1) #*+ -3) -- 2) * two) @ 2) @- -2)"
C_STR = "((((((((((((-8 #*@ -9) !# eight) @ -4) ** -9) !+ 8) *@ -1) +!& 3) !-# five) +!! ten) - -6) @+@ one) & 5)."

try:
    A = evaluate(A_STR)
    B = evaluate(B_STR)
    C = evaluate(C_STR)
    total = A + B - C
    result = {
        "final_answer": str(total),
        "evidence": {"A": A, "B": B, "C": C, "A_plus_B_minus_C": total},
    }
except Exception as e:
    result = {
        "final_answer": "UNSUPPORTED",
        "evidence": {"reason": str(e)},
    }

print(json.dumps(result, separators=(",", ":")))
