    "stork_tear_blocked": {"zebra_disarmed_by_someone"},      # Rule4 over Rule12
}

def closure(f):
    f = set(f)
    trace = []
    changed = True
    while changed:
        changed = False
        new = []

        def add(atom, why):
            if atom not in f:
                new.append((atom, why))

        # Rule1: goat watches pre-covid movie -> goat shouts at coyote
        if "goat_movie_released_1999" in f:
            add("goat_shouts_coyote", "Rule1")
        # Rule2: some animal shouts at coyote -> snake unites with vampire
        if any(a.endswith("_shouts_coyote") for a in f):
            add("snake_unites_vampire", "Rule2")
        # Rule5 (blocked by Rule10 if swan-castle evidence exists)
        if "mule_disarms_dachshund" in f and not (blockers["mule_borrow_blocked"] & f):
            add("mule_borrows_vampire_weapon", "Rule5")
        # Rule9
        if "mule_borrows_vampire_weapon" in f:
            add("vampire_destroys_camel_wall", "Rule9")
        # Rule7: some animal does not disarm beaver -> it smiles at vampire
        if "dugong_not_disarm_beaver" in f:
            add("dugong_smiles_vampire", "Rule7")
        # Rule6
        if "dugong_smiles_vampire" in f:
            add("vampire_not_call_lizard", "Rule6")
        # Rule3 / Rule8: primary-colored card -> falls on ostrich square
        if "stork_red_card" in f:
            add("stork_falls_ostrich", "Rule3")
        # Rule12 (blocked by Rule4 if zebra-disarm evidence exists)
        if "stork_falls_ostrich" in f and not (blockers["stork_tear_blocked"] & f):
            add("stork_tears_vampire_castle", "Rule12")
        # Rule13
        if "beetle_not_shout_reindeer" in f:
            add("reindeer_captures_vampire_king", "Rule13")
        # Rule14
        if "stork_tears_vampire_castle" in f and "snake_unites_vampire" in f:
            add("vampire_never_swims_crow", "Rule14")

        for atom, why in new:
            f.add(atom)
            trace.append(f"{atom} via {why}")
            changed = True
    return f, trace

