    "Canada": "Ottawa",
}


def _norm(country):
    c = country.strip()
    if c.startswith("the "):
        c = c[4:]
    return c


def CAP(country, claim):
    return REAL_CAPITALS.get(_norm(country)) == claim.strip()


def translate(expr):
    # Capital statements -> CAP(country, claim)
    s = re.sub(
        r"\(The capital of (.+?) is (.+?)\.\)",
        lambda m: 'CAP("%s","%s")' % (m.group(1), m.group(2)),
