PREFS = {("R1", "R2"), ("R1", "R5"), ("R4", "R2"), ("R4", "R5")}


def resolve(pos, neg):
    """Defeasible resolution: True if a positive rule wins, False if only
    negative rules apply, None if unresolved."""
    for n in neg:
        if not any((p, n) in PREFS for p in pos):
            return None  # a negative rule is not defeated by a preferred positive rule
    if pos:
        return True
    if neg:
        return False
    return None


def dolphin_trades(monkey_money):
    pos, neg = [], []
    if DOLPHIN_HAS_VIOLET_CARD:
        pos.append("R1")
    if DOLPHIN_MOVIE_YEAR > ZIDANE_BIRTH_YEAR:
        pos.append("R4")                # does not fire: 1926 < 1972
    if DOLPHIN_MONEY > monkey_money:
        neg.append("R2")
    if DOLPHIN_TOOK_BIKE:
        neg.append("R5")
