VECS = [v for v in itertools.product(R, repeat=3) if any(v)]


def cross(a, b):
    return (a[1]*b[2] - a[2]*b[1],
            a[2]*b[0] - a[0]*b[2],
            a[0]*b[1] - a[1]*b[0])


def dot(a, b):
    return sum(x*y for x, y in zip(a, b))


def par(a, b):
    # nonzero vectors a, b are parallel (a line perpendicular to a plane has
    # direction parallel to the plane's normal) iff their cross product is zero
    return cross(a, b) == (0, 0, 0)


def check_A():
    # alpha ⊥ beta, alpha ∩ beta = l (direction na x nb), m ⊥ l ; conclusion m ⊥ beta
    total, ce = 0, None
    for na in VECS:
        for nb in VECS:
            if dot(na, nb) != 0:
                continue
            l = cross(na, nb)
            for dm in VECS:
                if dot(dm, l) != 0:
                    continue
                total += 1
                if not par(dm, nb) and ce is None:
                    ce = (na, nb, dm)
    return total, ce


def check_B():
    # alpha ∩ gamma = m (direction na x ng), alpha ⊥ gamma, beta ⊥ gamma ; conclusion m ⊥ beta
    total, ce = 0, None
    for na in VECS:
        for ng in VECS:
            if dot(na, ng) != 0:
                continue
            dm = cross(na, ng)
            for nb in VECS:
                if dot(nb, ng) != 0:
                    continue
                total += 1
                if not par(dm, nb) and ce is None:
                    ce = (na, ng, nb, dm)
    return total, ce


def check_C():
    # alpha ⊥ gamma, beta ⊥ gamma, m ⊥ alpha ; conclusion m ⊥ beta
    total, ce = 0, None
    for na in VECS:
        for ng in VECS:
            if dot(na, ng) != 0:
                continue
            for nb in VECS:
                if dot(nb, ng) != 0:
                    continue
                for dm in VECS:
                    if not par(dm, na):
                        continue
                    total += 1
                    if not par(dm, nb) and ce is None:
                        ce = (na, ng, nb, dm)
    return total, ce


def check_D():
    # n ⊥ alpha, n ⊥ beta, m ⊥ alpha ; conclusion m ⊥ beta
    total, ce = 0, None
    for na in VECS:
        for nb in VECS:
            for dn in VECS:
                if not (par(dn, na) and par(dn, nb)):
                    continue
                for dm in VECS:
                    if not par(dm, na):
                        continue
                    total += 1
                    if not par(dm, nb) and ce is None:
                        ce = (na, nb, dn, dm)
    return total, ce


results = {}
for name, fn in [("A", check_A), ("B", check_B), ("C", check_C), ("D", check_D)]:
    total, ce = fn()
    results[name] = ce
    print(f"Option {name}: hypothesis instances checked = {total}")
    if ce is None:
        print(f"  Option {name}: no counterexample in grid {R}")
    else:
        print(f"  Option {name}: counterexample (normals/directions) = {ce}")

sufficient = sorted(k for k, v in results.items() if v is None)
print("Options with no counterexample on the grid:", sufficient)

print("Note: A, B, C are refuted by explicit counterexamples (exact integer arithmetic).")
print("Note: D is sampled on the finite grid only; the universal claim follows algebraically:")
print("  n ⊥ alpha and n ⊥ beta give normal(alpha) ∥ normal(beta); m ⊥ alpha gives m ∥ normal(alpha) = normal(beta), so m ⊥ beta.")

if sufficient == ["D"]:
    print("CHECK PASS: the submitted answer D is the sufficient condition; A, B, C fail.")
else:
    print("CHECK FAIL: sufficient set on grid is", sufficient)
