    print("CHECK PASS: claimed value is attained by an exhaustive enumeration.")
else:
    print("CHECK FAIL: claimed value 255 is not attained under the same-column reading.")

# Secondary reading for context: total paths from P to any top-row square.
print("\nAny-top-column reading (for reference):")
for parity in (0, 1):
    for pcol in range(COLS):
        total = sum(paths_from(pcol, parity).values())
        print(f"  parity {parity}, P col {pcol}: total to top row = {total}")
        if total == CLAIMED:
