import json
from fractions import Fraction

def mul(A, B):
    return [[sum(A[i][k] * B[k][j] for k in range(2)) for j in range(2)] for i in range(2)]

def add(A, B):
    return [[A[i][j] + B[i][j] for j in range(2)] for i in range(2)]

def neg(A):
    return [[-A[i][j] for j in range(2)] for i in range(2)]

def norm(A):
    # induced infinity-norm (max absolute row sum), submultiplicative
    return max(sum(abs(A[i][j]) for j in range(2)) for i in range(2))

def mpow(A, n):
    R = [[Fraction(1), Fraction(0)], [Fraction(0), Fraction(1)]]
    for _ in range(n):
        R = mul(R, A)
    return R

def nth_root_exact(v, n):
    # returns exact value of v^(1/n) when v is 0 or 1; None otherwise
    if v == 0:
        return Fraction(0)
    if v == 1:
        return Fraction(1)
    return None

I = [[Fraction(1), Fraction(0)], [Fraction(0), Fraction(1)]]
N = [[Fraction(0), Fraction(1)], [Fraction(0), Fraction(0)]]

x = I
y = add(neg(I), N)          # y = -I + N
s = add(x, y)               # x + y = N

assert s != [[Fraction(0)] * 2 for _ in range(2)]   # x + y != 0

M = 12
s_roots = []
x_roots = []
for n in range(1, M + 1):
    s_roots.append(nth_root_exact(norm(mpow(s, n)), n))
    x_roots.append(nth_root_exact(norm(mpow(x, n)), n))

# Tail behaviour (n >= 2) decides the limits
s_tail_zero = all(r == 0 for r in s_roots[1:])
x_tail_zero = all(r == 0 for r in x_roots[1:])
x_tail_values = sorted({str(r) for r in x_roots[1:]})

if s_tail_zero and not x_tail_zero and all(r == 1 for r in x_roots[1:]):
    final_answer = "no"
elif s_tail_zero and x_tail_zero:
    final_answer = "yes"
else:
    final_answer = "UNSUPPORTED"

evidence = {
    "x": "I (identity 2x2)",
    "y": "-I + N, N=[[0,1],[0,0]]",
    "x_plus_y": "N, N^2=0",
    "norm": "max absolute row sum",
    "limit_of_norm_(x+y)^n^(1/n)_tail_is_0": s_tail_zero,
    "limit_of_norm_x^n^(1/n)_tail_values": x_tail_values,
    "limit_of_norm_x^n^(1/n)_is_0": x_tail_zero,
    "checked_n_up_to": M,
}

print(json.dumps({"final_answer": final_answer, "evidence": evidence}, separators=(",", ":")))
