def main():
    # Ground facts from the game state.
    facts = {
        ("suspects", "duck", "butterfly"),
        ("name", "fish", "Paco"),
        ("name", "reindeer", "Peddi"),
    }
    # Explicit negative facts. Closed-world reading: only these are denied.
    negfacts = {
        ("hugs", "ant", "flamingo"),
    }

    # Forward chaining to a fixpoint.
    changed = True
    while changed:
        changed = False
        new_pos, new_neg = set(), set()

        fish_names = [v for (t, e, v) in facts if t == "name" and e == "fish"]
        reindeer_names = [v for (t, e, v) in facts if t == "name" and e == "reindeer"]

        # Rule1: reindeer hugs crab if reindeer's name and fish's name share first letter.
        for r in reindeer_names:
            for f in fish_names:
                if r and f and r[0] == f[0]:
                    new_pos.add(("hugs", "reindeer", "crab"))

        # Rule2: whoever suspects the butterfly also suspects the otter.
        for (t, x, y) in list(facts):
            if t == "suspects" and y == "butterfly":
                new_pos.add(("suspects", x, "otter"))

        # Rule3: if ant does not hug flamingo, flamingo reveals a secret to otter.
        if ("hugs", "ant", "flamingo") in negfacts:
            new_pos.add(("reveals_secret", "flamingo", "otter"))

        # Rule4: if flamingo reveals secret to otter and duck suspects otter,
        # then the otter is not going to hide her cards from the dragon.
        if ("reveals_secret", "flamingo", "otter") in facts and \
           ("suspects", "duck", "otter") in facts:
            new_neg.add(("hides", "otter", "dragon"))

        if not new_pos <= facts:
            facts |= new_pos
            changed = True
        if not new_neg <= negfacts:
            negfacts |= new_neg
            changed = True

    target_pos = ("hides", "otter", "dragon")
    if target_pos in facts:
        verdict = "proved"
    elif target_pos in negfacts:
        verdict = "disproved"
    else:
        verdict = "unknown"

    submitted = "proved"  # submitted answer: "Proven"

    print("Derived: reindeer hugs crab =", ("hugs", "reindeer", "crab") in facts)
    print("Derived: duck suspects otter =", ("suspects", "duck", "otter") in facts)
    print("Derived: flamingo reveals secret to otter =",
          ("reveals_secret", "flamingo", "otter") in facts)
    print("Derived: otter NOT hide cards from dragon =",
          ("hides", "otter", "dragon") in negfacts)
    print("Computed verdict for 'otter hides cards from dragon':", verdict)
    print("Submitted verdict:", "Proven")

    if verdict == submitted:
        print("CHECK PASS")
    else:
        print("CHECK FAIL")


if __name__ == "__main__":
    main()
