    result = {
        "final_answer": "UNSUPPORTED",
        "evidence": {
            "options_identical": True,
            "distinct_texts": len(distinct_texts),
            "reason": "Sarcasm depends on tone, speaker intent, and context, and the two options are byte-identical, so no computation can separate them."
